document.head.insertAdjacentHTML('beforeend','<link rel="stylesheet" href="analytics.css">');document.querySelector('.campaign').insertAdjacentHTML('afterend','<button id="exportBtn" class="export-btn">↗ EXPORTAR REPORT</button>');document.querySelector('#exportBtn').onclick=()=>window.print();
const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(v||0),pct=v=>new Intl.NumberFormat('pt-BR',{style:'percent',maximumFractionDigits:2}).format(v||0),icon=n=>`https://www.google.com/s2/favicons?domain=${({Meli:'mercadolivre.com.br',Shopee:'shopee.com.br',Amazon:'amazon.com.br',MagaLu:'magazineluiza.com.br',TikTok:'tiktok.com',Via:'casasbahia.com.br',WCO:'webcontinental.com.br',Madeira:'madeiramadeira.com.br',Kabum:'kabum.com.br',Carrefour:'carrefour.com.br',Leroy:'leroymerlin.com.br',Martins:'martinsatacado.com.br',Site:'oficialwebshop.com.br',VD:'oficialwebshop.com.br'}[n]||'oficialwebshop.com.br')}&sz=64`;
const sum=(rows,k)=>rows.reduce((s,r)=>s+(+r[k]||0),0),group=(rows,key)=>Object.values(rows.reduce((a,r)=>{const x=r[key]||'Outros';a[x]??={name:x,gmv:0,produto:0,frete:0,custo:0,liquido:0,pedidos:0};['gmv','produto','frete','custo','liquido','pedidos'].forEach(k=>a[x][k]+=+r[k]||0);return a},{}));
function metric(name,rows,days){const g=sum(rows,'gmv'),p=sum(rows,'produto'),l=sum(rows,'liquido'),c=sum(rows,'custo'),orders=sum(rows,'pedidos'),proj=g/Math.max(days,1)*30;return{name,g,p,cm2:p?l/p:0,ir:c?l/c:0,orders,ticket:orders?g/orders:0,proj}}
const variation=(a,b)=>b?(a/b-1):null,trend=(label,v)=>`<div class="trend ${v==null?'flat':v>.001?'up':v<-.001?'down':'flat'}"><span>${label}</span><b>${v==null?'—':`${v>=0?'▲':'▼'} ${Math.abs(v*100).toFixed(1)}%`}</b></div>`;
function card(m,t){return `<article class="card"><div class="card-head">${m.name}</div><div class="card-body"><div class="main">${money(m.g)}</div><div class="sub">VALOR PRODUTO</div><div class="product">${money(m.p)}</div><div class="split"><div><span>CM2</span><b>${pct(m.cm2)}</b></div><div><span>IR</span><b>${pct(m.ir)}</b></div></div>${t?`<div class="trend-row">${trend('DoD',t.dod)}${trend('MoM',t.mom)}${trend('YoY',t.yoy)}</div>`:`<div class="projection"><span>PROJEÇÃO</span><b>${money(m.proj)}</b></div>`}</div></article>`}
function bars(el,items){const max=Math.max(...items.map(x=>x.v),1);el.innerHTML=items.map(x=>`<div class="bw"><div class="bar" style="height:${x.v/max*88}%">${Math.round(x.v)}%</div><label>${x.n}</label></div>`).join('')}
function render(d){const rows=d.rows,cut=new Date((d.cutoff||new Date().toISOString().slice(0,10))+'T12:00:00'),days=cut.getDate(),all=metric('GMV',rows,days),official=metric('OFICIAL',rows.filter(r=>r.empresa.toLowerCase().includes('oficial')),days),prioriza=metric('PRIORIZA',rows.filter(r=>r.empresa.toLowerCase().includes('prioriza')),days),market=metric('MARKETPLACE',rows.filter(r=>!['VD','Site'].includes(r.canal)),days),vd=metric('VD',rows.filter(r=>r.canal==='VD'),days),site=metric('SITE',rows.filter(r=>r.canal==='Site'),days),cm=new Map(d.comparisons.map(x=>[x.canal,x])),calc=arr=>{const c=arr.length?arr:d.comparisons,sa=k=>c.reduce((s,x)=>s+x[k],0);return{dod:variation(sa('dodAtual'),sa('dodAnterior')),mom:variation(sa('momAtual'),sa('momAnterior')),yoy:variation(sa('momAtual'),sa('yoyAnterior'))}},totalTrend=calc([]),marketTrend=calc(d.comparisons.filter(x=>!['VD','Site'].includes(x.canal)));document.querySelector('#cards').innerHTML=[card(all,totalTrend),card(official),card(prioriza),card(market,marketTrend),card(vd,calc([cm.get('VD')].filter(Boolean))),card(site,calc([cm.get('Site')].filter(Boolean)))].join('');document.querySelector('#cutoff').textContent=cut.toLocaleDateString('pt-BR');document.querySelector('#updated').textContent=new Date(d.updatedAt).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});document.querySelector('#financial').innerHTML=[['CM2',money(all.p*all.cm2)],['FRETE',money(sum(rows,'saldoFrete'))],['TICKET MÉDIO',money(all.ticket)],['PROVISIONAMENTOS','A integrar DAX']].map(x=>`<div class="fin"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');const channels=group(rows,'canal').sort((a,b)=>b.gmv-a.gmv),max=channels[0]?.gmv||1;document.querySelector('thead tr').innerHTML='<th>Canal</th><th>GMV</th><th>GMV %</th><th>CM2</th><th>IR</th><th>DoD</th><th>MoM</th><th>YoY</th>';document.querySelector('#channelRows').innerHTML=channels.slice(0,14).map((c,i)=>{const co=cm.get(c.name)||{},t={dod:variation(co.dodAtual,co.dodAnterior),mom:variation(co.momAtual,co.momAnterior),yoy:variation(co.momAtual,co.yoyAnterior)},details=rows.filter(r=>r.canal===c.name),cell=v=>`<span class="delta ${v==null?'flat':v>=0?'up':'down'}">${v==null?'—':`${v>=0?'▲':'▼'} ${Math.abs(v*100).toFixed(1)}%`}</span>`;return `<tr class="channel-main" data-drill="d${i}"><td><span class="chev">›</span><img class="logo" src="${icon(c.name)}">${c.name}</td><td><strong>${money(c.gmv)}</strong></td><td>${pct(c.gmv/all.g)}</td><td>${pct(c.produto?c.liquido/c.produto:0)}</td><td>${pct(c.custo?c.liquido/c.custo:0)}</td><td>${cell(t.dod)}</td><td>${cell(t.mom)}</td><td>${cell(t.yoy)}</td></tr><tr id="d${i}" class="drill-row"><td colspan="8" class="drill-content"><div class="drill-grid">${details.map(r=>`<div class="drill-item"><b>${r.empresa} • ${r.subcanal||r.canal}</b><span>${money(r.gmv)} • ${r.pedidos} pedidos • TM ${money(r.pedidos?r.gmv/r.pedidos:0)}</span></div>`).join('')}</div></td></tr>`}).join('');document.querySelectorAll('.channel-main').forEach(tr=>tr.onclick=()=>{document.querySelector('#'+tr.dataset.drill).classList.toggle('open');tr.querySelector('.chev').textContent=document.querySelector('#'+tr.dataset.drill).classList.contains('open')?'⌄':'›'});document.querySelector('#mixRows').innerHTML=rows.sort((a,b)=>b.gmv-a.gmv).slice(0,12).map(r=>`<div class="mix-row"><span>${r.empresa} • ${r.subcanal||r.canal}</span><div class="track"><i style="width:${r.gmv/max*100}%"></i></div><b>${money(r.gmv)}</b></div>`).join('');bars(document.querySelector('#buChart'),[{n:'Marketplace',v:market.g/all.g*100},{n:'VD',v:vd.g/all.g*100},{n:'Site',v:site.g/all.g*100}]);bars(document.querySelector('#modalChart'),[{n:'Oficial',v:official.g/all.g*100},{n:'Prioriza',v:prioriza.g/all.g*100}]);document.querySelector('#loading').classList.add('hide')}
import('./app-v3.js');
